const timestamp = Date.now()
const email = "test_" + timestamp + "@email.com"
const password = "test123"

pm.sendRequest({
    url: pm.variables.replaceIn("{{base_url}}/usuarios"),
    method: "POST",
    header: { "Content-Type": "application/json" },
    body: JSON.stringify({
        nome: "UserTest",
        email: email,
        password: password,
        administrador: "true"
    })
}, function (err, response) {
    if (err) {
        console.error(err)
        return
    }
    const json = response.json()
    pm.collectionVariables.set("id_usuario", json._id)
    pm.collectionVariables.set("emailbase", email)
    console.log(" ------------- > Registro realizado")

    pm.sendRequest({
        url: pm.variables.replaceIn("{{base_url}}/login"),
        method: "POST",
        header: { "Content-Type": "application/json" },
        body: JSON.stringify({
            email: pm.collectionVariables.get("emailbase"),
            password: password
        })
    }, function (err, response) {
        if (err) {
            console.error("Ocorreu um erro durante o login -> ", err)
            return
        }
        const json = response.json()
        console.log(json)
        console.log(json.authorization.replace("Bearer ", ""))
        const token = json.authorization.replace("Bearer ", "")

        pm.sendRequest({
            url: pm.variables.replaceIn("{{base_url}}/carrinhos"),
            method: "POST",
            header: {
                "Authorization": "Bearer " + token,
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                produtos: [{
                    idProduto: "BeeJh5lz3k6kSIzA",
                    quantidade: 5
                }]
            })
        }, function(err, response){ 
            if(err){
                console.error("Ocorreu um erro ao cadastrar um carrinho: ", err)
            }
            console.log(response.status)
            console.log("Cadastrou o carrinho!")
            const j = response.json() 
            console.log(j._id)
        })
    })
})

